CREATE TABLE `app_chyj_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'APP版本号',
  `channel` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'APP渠道',
  `req_type` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '[screen_off]灭屏\n[back_first_open]安装后启动\n[imei_per]imei授权后\n[wel_click_confirm]欢迎页首次进入、点击同意\n[wel_agine_enter]欢迎页二次进入\n[wel_splashad_req]开屏广告请求\n[wel_guiyin]归因策略请求',
  `imei` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'IMEI',
  `oaid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'OAID',
  `android_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'Android ID',
  `vendor` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '生产厂商',
  `model` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设备型号',
  `strategy_target` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '归因命中标识',
  `strategy_key` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '策略[audit]审核[common]正常[patrol]巡检',
  `strategy_version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '策略版本',
