CREATE TABLE `app_jshgj_device_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `device_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设备ID[AndroidID]',
  `date` date NOT NULL COMMENT '日期',
  `channel` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '渠道',
  `version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '版本',
  `vendor` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '厂商',
  `model` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '型号',
  `ad_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '广告标记时间',
  `click_info` json DEFAULT NULL COMMENT '点击信息（代码位）',
  `click_value` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '点击价值',
  `lock_show` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '锁屏展示',
  `lock_value` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '锁屏价值',
  `total_value` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '当日价值',
  `update_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `create_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_date_device` (`date`,`device_id`),
  KEY `idx_device` (`device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='设备留存记录';


