CREATE TABLE `app_ldzs_huawei` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `account_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `imei` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'IMEI的MD5',
  `oaid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'OAID',
  `android_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'ANDROIDID的MD5',
  `device_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设备ID[AndroidID]',
  `channel` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '渠道',
  `vendor` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '厂商',
  `ip` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'IP',
  `ua` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户代理',
  `ts` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '点击广告时间戳',
  `campaign_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '任务ID',
  `campaign_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '任务名称',
  `aid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告计划ID',
  `aid_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告计划名称',
  `cid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告素材ID',
  `cid_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告素材名称',
  `transunique_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '统一跟踪ID',
  `callback` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '回调参数',
  `tracking_enabled` tinyint(1) NOT NULL DEFAULT '0' COMMENT '跟踪画像[0]不允许[1]允许',
  `active_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '激活时间',
  `active_status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '激活状态 [0]默认[1]激活待通知[2]激活已通知',
  `active_times` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '激活通知失败次数',
  `keep_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '次留时间',
  `keep_status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '次留状态 [0]默认[1]次留待通知[2]次留已通知',
  `keep_times` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '留存通知失败次数',
  `action_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为时间',
  `action_status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为 [0]默认[1]待通知[2]已通知',
  `action_times` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为通知失败次数',
  `update_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `create_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_ts_android` (`ts`,`android_id`),
  KEY `idx_ts_imei` (`ts`,`imei`),
  KEY `idx_ts_oaid` (`ts`,`oaid`),
  KEY `idx_active` (`active_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='归因设备-巨量';


