CREATE TABLE `app_ldzs_trade` (
  `trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易单号',
  `goods_no` bigint(20) NOT NULL COMMENT '商品单号',
  `account` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  `amount` decimal(14,2) NOT NULL COMMENT '交易金额',
  `channel` tinyint(1) NOT NULL COMMENT '付款渠道:[1]微信支付,[2]支付宝',
  `trade_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '交易状态:[0]支付中[1]支付成功[2]支付后退款[3]支付失败[4]关闭',
  `created_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int(11) NOT NULL DEFAULT '0' COMMENT '修改时间',
  `attach` json DEFAULT NULL COMMENT '附加数据',
  PRIMARY KEY (`trade_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='交易订单表';


CREATE TABLE `app_ldzs_vip` (
  `account` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  `expired_time` int(11) NOT NULL DEFAULT '0' COMMENT '到期时间',
  `created_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int(11) NOT NULL DEFAULT '0' COMMENT '修改时间',
  PRIMARY KEY (`account`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='用户已开通功能表';


CREATE TABLE `app_ldzs_vip_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `account` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  `pre_time` int(11) NOT NULL DEFAULT '0' COMMENT '购买前时间',
  `buy_time` int(11) NOT NULL DEFAULT '0' COMMENT '购买后时间',
  `trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易单号',
  `goods_sku` json DEFAULT NULL COMMENT '商品sku',
  `created_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='用户已开通记录表';


CREATE TABLE `app_ldzs_vivo` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
