CREATE TABLE `app_sstg_event_ad_revenue` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `time` bigint(20) unsigned NOT NULL DEFAULT '0' COMMENT '时间[例20230412141500]',
  `device_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设备ID',
  `amount` decimal(10,5) unsigned NOT NULL DEFAULT '0.00000' COMMENT '金额[元]',
