  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_time_device` (`time`,`device_id`),
  KEY `idx_device` (`device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;


