CREATE TABLE `app_xjbs_event_dialog` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uuid` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '唯一标识',
  `key_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '外弹场景key',
  `req_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '请求类型',
  `version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'APP版本号',
  `channel` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'APP渠道',
  `android_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'Android ID',
  `vendor` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '生产厂商',
  `model` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设备型号',
  `os_version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '系统版本',
  `update_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '更新事件',
  `create_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建事件',
  PRIMARY KEY (`id`),
  KEY `index_time` (`create_time`),
  KEY `index_android` (`android_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='外弹打点';


