CREATE TABLE `app_yboh_event_interval_group` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_type` varchar(30) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '事件类型',
  `start_end` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '开始-结束时间',
  `start_time` bigint(20) unsigned NOT NULL COMMENT '时段开始时间戳',
  `end_time` bigint(20) unsigned NOT NULL COMMENT '时段结束时间戳',
  `device_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设备ID',
  `max_level` int(11) DEFAULT NULL COMMENT '最高层级 0保底层 -1倒1层 404无法确定层级',
  `amount` decimal(12,4) unsigned NOT NULL DEFAULT '0.0000' COMMENT '预估回收',
  `info` json DEFAULT NULL COMMENT '广告信息',
  `create_time` bigint(20) unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `event_type` (`event_type`),
  KEY `device_id` (`device_id`),
  KEY `idx_time_device_amount` (`start_time`,`end_time`,`device_id`,`amount`),
  KEY `end_time` (`end_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='广告打点分时间统计表';


