  `times` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '请求次数',
  `created_time` int(10) unsigned NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_active_device` (`active_day`,`device_id`),
  KEY `idx_activate_keep_device` (`activate_day`,`activate_keep_num`,`device_id`),
  KEY `idx_install_keep_device` (`install_day`,`install_keep_num`,`device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;


