  `vendor` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '厂商',
  `ip` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'IP',
  `ua` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户代理',
  `model` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机型号',
  `mac` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'MAC去“:”后大写MD5',
  `ts` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '点击广告时间戳',
  `os` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '操作系统平台 [0]安卓[1]IOS[3]其他',
  `campaign_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告组ID',
  `campaign_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告组名称',
  `aid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告计划ID',
  `aid_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告计划名称',
  `cid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告创意ID',
  `cid_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告创意名称',
  `csite` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告投放位置',
  `convert_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '转化ID',
  `request_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '请求下发的ID',
  `union_site` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '对外广告位编码',
  `callback_url` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '回调地址',
  `active_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '激活时间',
  `active_status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '激活状态 [0]默认[1]激活待通知[2]激活已通知',
  `active_times` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '激活通知失败次数',
  `keep_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '次留时间',
  `keep_status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '次留状态 [0]默认[1]次留待通知[2]次留已通知',
  `keep_times` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '留存通知失败次数',
  `action_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为时间',
  `action_status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为 [0]默认[1]待通知[2]已通知',
  `action_times` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为通知失败次数',
  `update_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `create_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_imei_deviceid_aid_accountid` (`imei`,`device_id`,`aid`,`account_id`),
  KEY `idx_androidid_deviceid_aid_accountid` (`android_id`,`device_id`,`aid`,`account_id`),
  KEY `idx_oaid_deviceid_aid_accountid` (`oaid`,`device_id`,`aid`,`account_id`),
  KEY `idx_active` (`active_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='归因设备-巨量';


CREATE TABLE `app_yst_bd` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `account_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `imei` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'IMEI的MD5',
  `oaid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'OAID',
  `android_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'ANDROIDID的MD5',
  `device_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设备ID[AndroidID]',
  `channel` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '渠道',
  `vendor` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '厂商',
  `ip` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'IP',
  `ua` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '用户代理',
  `model` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '手机型号',
  `ts` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '点击广告时间戳',
  `os` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '操作系统平台 [2]安卓[1]IOS',
  `os_version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '系统版本',
  `campaign_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告单元ID',
  `aid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告计划ID',
  `cid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告创意ID',
  `click_id` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '唯一标识',
  `callback_url` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '回调地址',
  `active_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '激活时间',
  `active_status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '激活状态 [0]默认[1]激活待通知[2]激活已通知',
  `active_times` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '激活通知失败次数',
  `keep_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '次留时间',
  `keep_status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '次留状态 [0]默认[1]次留待通知[2]次留已通知',
  `keep_times` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '留存通知失败次数',
  `action_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为时间',
  `action_status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为 [0]默认[1]待通知[2]已通知',
  `action_times` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为通知失败次数',
  `update_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `create_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_imei_deviceid_aid_accountid` (`imei`,`device_id`,`aid`,`account_id`),
  KEY `idx_androidid_deviceid_aid_accountid` (`android_id`,`device_id`,`aid`,`account_id`),
  KEY `idx_oaid_deviceid_aid_accountid` (`oaid`,`device_id`,`aid`,`account_id`),
  KEY `idx_deviceid_ts` (`device_id`,`ts`),
  KEY `idx_active` (`active_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='归因设备-百度';


CREATE TABLE `app_yst_device_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `device_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设备ID[AndroidID]',
  `date` date NOT NULL COMMENT '日期',
  `channel` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '渠道',
  `version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '版本',
  `vendor` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '厂商',
  `model` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '型号',
  `ad_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '广告标记时间',
  `click_info` json DEFAULT NULL COMMENT '点击信息（代码位）',
  `click_value` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '点击价值',
  `lock_show` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '锁屏展示',
  `lock_value` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '锁屏价值',
  `total_value` decimal(10,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '当日价值',
  `update_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `create_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_date_device` (`date`,`device_id`),
  KEY `idx_device` (`device_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='设备留存记录';


