CREATE TABLE `app_zhbbq_temp` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `umid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '友盟ID',
  `channel` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '渠道',
  `imei` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'IMEI',
  `oaid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'OAID',
  `android_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'Android ID',
  `vendor` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '生产厂商',
  `model` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '设备型号',
  `mac` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'MAC地址',
  `ip` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'IP地址',
  `location` json NOT NULL COMMENT '定位信息',
  `wifi_list` json NOT NULL COMMENT 'WiFi列表',
  `app_list` json NOT NULL COMMENT '应用列表',
  `net` json NOT NULL COMMENT '网络名称',
  `os_version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '系统版本',
  `version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT 'APP版本',
  `source` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '[1]巨量[2]快手',
  `ad_id` bigint(20) unsigned NOT NULL DEFAULT '0' COMMENT '点击检测ID',
  `ad_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '归因时间',
  `active_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '激活时间',
  `keep_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '次留时间',
  `action_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '关键行为时间',
  `action_info` json DEFAULT NULL COMMENT '关键行为信息',
  `account_id` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `aid` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '广告计划ID',
  `update_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '更新时间',
  `create_time` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '创建时间',
  `more_keep` int(11) NOT NULL DEFAULT '0' COMMENT '多次留存，二进制位标识',
  `hour_keep` int(11) NOT NULL DEFAULT '0' COMMENT '24小时留存：0=未留存，1=已留存',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_device` (`android_id`),
  KEY `idx_create` (`create_time`),
  KEY `idx_device_put` (`android_id`,`aid`,`account_id`),
  KEY `idx_active` (`active_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='设备信息';


CREATE TABLE `app_zhbbq_trade` (
  `trade_no` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '交易单号',
  `goods_no` bigint(20) NOT NULL COMMENT '商品单号',
  `account` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '账号',
  `amount` decimal(14,2) NOT NULL COMMENT '交易金额',
  `channel` tinyint(1) NOT NULL COMMENT '付款渠道:[1]微信支付,[2]支付宝',
  `trade_status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '交易状态:[0]支付中[1]支付成功[2]支付后退款[3]支付失败[4]关闭',
  `created_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `updated_time` int(11) NOT NULL DEFAULT '0' COMMENT '修改时间',
  `attach` json DEFAULT NULL COMMENT '附加数据',
  PRIMARY KEY (`trade_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC COMMENT='交易订单表';


