CREATE TABLE `com_middle_live` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `active_date` date NOT NULL COMMENT '日期',
  `android_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'Android ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT 'APP版本',
  `channel` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '渠道',
  `vendor` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '厂商',
  `os_version` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '操作系统版本',
  `timekeeping` bigint(20) NOT NULL DEFAULT '0' COMMENT '累积时间【毫秒】',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_app_date_android` (`app_code`,`active_date`,`android_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='活跃统计';


CREATE TABLE `com_mkt_advertiser` (
  `advertiser_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `advertiser_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '广告主名称',
  `agency_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '代理名称',
  `platform` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '投放平台',
  `account_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '帐户ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '所属应用',
  `status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '状态 1-正常 0-禁用',
  `launch_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '投放方式0-次留双出 1-关键行为',
  `active_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '激活类型[1]开屏[2]归因[3]回收[4]自定义',
  `active_value` json DEFAULT NULL COMMENT '激活定义设置',
  `action_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '关键行为类型[0]不触发[1]回收率[2]加桌[3]自定义',
  `action_value` json DEFAULT NULL COMMENT '关键行为定义',
  `action_revenue` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '关键行为:回收率、回收金额',
  `updated_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  `created_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `deleted_time` int(11) NOT NULL DEFAULT '0' COMMENT '删除时间 0-未删除',
  `is_mark` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否标记:[0]未标记[1]已标记',
  `extra` json DEFAULT NULL COMMENT '额外配置',
  `notify_discount` tinyint(1) NOT NULL DEFAULT '0' COMMENT '扣量百分比',
  `keep_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '留存定义[0]自然日[1]24小时',
  `notify_fill` tinyint(1) NOT NULL DEFAULT '0' COMMENT '被扣补量[0]否[1]是-留存满足',
  PRIMARY KEY (`advertiser_id`),
  KEY `idx_app` (`app_code`),
  KEY `idx_account` (`account_id`),
  KEY `idx_agency` (`agency_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='投放-广告主';


