  `version` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '版本号',
  `channel` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '渠道',
  `is_new` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1-新增用户 2-deu用户 3-激活 4-deu老用户 5-DAU',
  `user_num` int(11) NOT NULL DEFAULT '0' COMMENT '用户数',
  `create_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `date_code_event_version_channel_vendor` (`app_code`,`date`,`is_new`,`version`,`channel`,`vendor`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;


CREATE TABLE `mkt_advertiser` (
  `advertiser_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '广告主ID',
  `advertiser_name` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '广告主名称',
  `agency_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '代理名称',
  `platform` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '投放平台',
  `account_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '帐户ID',
  `app_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '所属应用',
  `status` tinyint(3) unsigned NOT NULL DEFAULT '0' COMMENT '状态 1-正常 0-禁用',
  `launch_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '投放方式0-次留双出 1-关键行为',
  `active_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '激活类型[1]开屏[2]归因[3]回收[4]自定义',
  `active_value` json DEFAULT NULL COMMENT '激活定义设置',
  `action_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '关键行为类型[0]不触发[1]回收率[2]加桌[3]自定义',
  `action_value` json DEFAULT NULL COMMENT '关键行为定义',
  `action_revenue` decimal(12,2) unsigned NOT NULL DEFAULT '0.00' COMMENT '关键行为:回收率、回收金额',
  `updated_time` int(11) NOT NULL DEFAULT '0' COMMENT '更新时间',
  `created_time` int(11) NOT NULL DEFAULT '0' COMMENT '创建时间',
  `deleted_time` int(11) NOT NULL DEFAULT '0' COMMENT '删除时间 0-未删除',
  `is_mark` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否标记:[0]未标记[1]已标记',
  `extra` json DEFAULT NULL COMMENT '额外配置',
  `notify_discount` tinyint(1) NOT NULL DEFAULT '0' COMMENT '扣量百分比',
  `keep_type` tinyint(4) NOT NULL DEFAULT '0' COMMENT '留存定义[0]自然日[1]24小时',
  `notify_fill` tinyint(1) NOT NULL DEFAULT '0' COMMENT '被扣补量[0]否[1]是-留存满足',
  PRIMARY KEY (`advertiser_id`),
  KEY `idx_app` (`app_code`),
  KEY `idx_account` (`account_id`),
  KEY `idx_agency` (`agency_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC COMMENT='投放-广告主';


CREATE TABLE `placement_account` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '代码位创建-平台账号表',
  `platform` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '平台 ks-快手，csj-穿山甲，ylh-优量汇，topon',
  `platform_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '平台名称',
  `subject` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '账号主体',
  `conf` json DEFAULT NULL COMMENT '账号配置',
  `status` tinyint(3) unsigned DEFAULT NULL COMMENT '状态 1-正常 0-停用',
  `created_time` int(11) DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE `placement_app` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '代码位创建-应用',
  `account_id` int(11) DEFAULT NULL COMMENT '所属账号',
  `app_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '应用ID',
  `app_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '应用名称',
  `package_name` varchar(230) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '包名',
  `status` tinyint(4) DEFAULT NULL COMMENT '应用状态 1-正常 0-停用',
  `created_time` int(11) DEFAULT NULL COMMENT '创建时间',
  `updated_time` int(11) DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `account_id` (`account_id`,`app_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE `placement_list` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '代码位创建-代码位列表',
  `create_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建的批次',
  `account_id` int(11) DEFAULT NULL COMMENT '账号ID',
  `platform` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '平台 ks-快手，csj-穿山甲，ylh-优量汇，topon',
  `app_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'app_id',
  `app_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'app_name',
  `placement_ad_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '广告类型',
  `placement_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '代码位名称',
  `placement_cpm` decimal(11,4) DEFAULT NULL COMMENT '设置的cpm',
  `set_cpm_result` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '设置cpm结果',
  `placement_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '代码位ID',
  `updated_time` int(11) DEFAULT NULL COMMENT '更新时间',
  `created_time` int(11) DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `create_key` (`create_key`),
  KEY `placement_id` (`placement_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE `placement_topon` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT 'topon广告位列表',
  `account_id` int(11) DEFAULT NULL COMMENT '账号ID',
  `app_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'appid',
  `app_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'app名称',
  `topon_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'topon广告位名称',
  `ad_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '广告类型',
  `topon_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'topon广告位ID',
  `created_time` int(11) DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `topon_id` (`topon_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;


CREATE TABLE `placement_topon_list` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '代码位创建-代码位列表',
  `create_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建的批次',
